svg.script:
(() => {
  const D = {"total":49,"totalMin":2715,"phases":[{"title":"Node Core & Project Setup","color":"#3fb950","y":300,"topics":[["Project Setup",45,["npm init, scripts, \"type\": \"module\"","TypeScript strict + tsx watch","ESLint flat config + Prettier","src/ folder: app.ts vs server.ts"]],["Config & Env",30,["Load .env with --env-file / dotenv","Validate env with a zod schema","Export one typed config object"]],["Modules & File System",60,["ESM import / export, dynamic import()","fs/promises read, write, readdir, mkdir","path.join / resolve, import.meta.dirname","Build a JSON file-backed data store"]],["Events & Streams",75,["class extends EventEmitter, on / once / emit","Readable / Transform streams","stream/promises pipeline()","Stream a large file to an HTTP response"]],["Async Patterns",45,["Promise.all / allSettled / race","for await...of over async iterators","AbortController + AbortSignal.timeout"]],["Process & CLI",45,["process.argv with util.parseArgs","Exit codes, SIGINT / SIGTERM handlers","unhandledRejection / uncaughtException"]],["Raw HTTP Server",90,["http.createServer((req, res) => ...)","Route by method + URL pathname","Parse a JSON request body","In-memory CRUD for /todos, no framework"]],["Workers & Crypto",45,["worker_threads for CPU-heavy work","crypto.randomUUID, createHash, createHmac","cluster.fork() one worker per CPU"]]]},{"title":"REST API with Express","color":"#38bdf8","y":736,"topics":[["Routing & Structure",45,["express.Router() per resource","Routes -> controllers -> services","Mount versioned routes at /api/v1"]],["Middleware",45,["Request-logger middleware","express.json({ limit }) body parser","asyncHandler wrapper for async routes"]],["Validation",45,["zod schemas for body, params, query","validate(schema) middleware","Return 400 / 422 with field errors"]],["Error Handling",45,["AppError class with statusCode","Central error middleware + 404 handler","Hide stack traces in production"]],["CRUD Resource",75,["GET list / one, POST, PATCH, DELETE","Status codes 200, 201, 204, 404","Map entities to response DTOs"]],["Pagination & Filters",45,["limit / offset and cursor pagination","?sort=-createdAt parser","Build filters from query safely"]],["File Uploads",45,["multer with size & MIME limits","Save to disk, return file URL"]],["Security Middleware",30,["helmet(), cors() allow-list","express-rate-limit per IP"]],["API Docs",45,["OpenAPI spec from zod schemas","Serve with swagger-ui-express"]]]},{"title":"Database, Cache & Auth","color":"#818cf8","y":1236,"topics":[["PostgreSQL + Prisma",90,["Model schema.prisma with relations","prisma migrate dev, seed script","include / select relations","$transaction for multi-step writes"]],["Repository Layer",45,["UserRepository interface","Prisma and in-memory implementations","Inject repositories into services"]],["Redis Cache",60,["ioredis client setup","Cache-aside get / set with TTL","Invalidate keys on writes"]],["Password Auth",45,["Hash with argon2 / bcrypt","POST /signup and POST /login"]],["JWT & Refresh",75,["Sign short-lived access tokens","requireAuth middleware","Refresh-token rotation stored in DB","Logout revokes refresh tokens"]],["RBAC",45,["Roles on the user model","authorize(\"admin\") middleware","Resource ownership checks"]],["Account Flows",60,["Email verification token","Forgot / reset password endpoints"]],["MongoDB (Bonus)",60,["Mongoose schema, model, validators","populate() and an aggregation pipeline"]]]},{"title":"Real-time, Jobs & Testing","color":"#e879f9","y":1672,"topics":[["WebSockets",60,["Socket.IO on the HTTP server","JWT auth on handshake","Rooms + broadcast events"]],["Job Queues",75,["BullMQ Queue + Worker","Retries with exponential backoff","Delayed jobs + repeatable cron jobs"]],["Email & Storage",60,["nodemailer emails sent via the queue","S3 presigned upload URLs","Resize images with sharp in a job"]],["Webhooks",45,["Stripe Checkout session endpoint","Verify webhook signature (raw body)","Idempotent webhook handler"]],["Unit Tests",60,["Vitest setup","Test services with fake repositories","vi.fn() mocks and spies"]],["Integration Tests",75,["Supertest against the Express app","Testcontainers Postgres + Redis","Seed / truncate between tests"]],["Logging & Health",60,["pino + pino-http with requestId","AsyncLocalStorage request context","/health/live and /health/ready","Graceful shutdown on SIGTERM"]]]},{"title":"Microservices & Events","color":"#fb923c","y":2108,"topics":[["Monorepo",45,["npm workspaces: services/* + packages/*","Shared packages: config, logger, errors"]],["Service Template",45,["Bootstrap: config, logger, health, shutdown","Scaffold each service from it","One database per service"]],["API Gateway",60,["http-proxy-middleware route per service","Verify JWT once at the gateway","Forward user claims + x-request-id"]],["Service HTTP Clients",45,["undici client per downstream service","Typed SDK package per service"]],["RabbitMQ Events",75,["amqplib exchange, queues, bindings","Publish / consume with ack / nack","Dead-letter queue for failures","zod-validated versioned event schemas"]],["Outbox & Idempotency",60,["Write event row in the same DB tx","Relay worker publishes outbox rows","Store processed message IDs, skip dupes"]],["Order Saga",60,["order.created -> payment -> stock flow","Compensating actions on failure","Persist saga state"]],["Resilience",60,["Timeouts + retries with jitter (p-retry)","Circuit breaker with opossum + fallback","Redis rate limit shared across instances"]],["gRPC (Bonus)",45,[".proto file + @grpc/grpc-js server & client"]]]},{"title":"Containers, Observability & Ship","color":"#fbbf24","y":2608,"topics":[["Dockerfile",45,["Multi-stage build on node:22-alpine","npm ci --omit=dev, run as non-root",".dockerignore + HEALTHCHECK"]],["Docker Compose",60,["Gateway + services + Postgres, Redis, RabbitMQ","depends_on with healthchecks","docker compose up runs everything"]],["Tracing",60,["OpenTelemetry SDK auto-instrumentation","Propagate traceparent over HTTP + messages","View a request across services in Jaeger"]],["Metrics",45,["prom-client histograms per route","Expose /metrics, scrape with Prometheus"]],["E2E & Load Test",60,["E2E: signup -> order -> pay -> notify","k6 / autocannon load test the gateway"]],["CI/CD",60,["GitHub Actions: lint, test, build","Build & push an image per service"]],["Kubernetes",60,["Deployment + Service per microservice","ConfigMap, Secret, liveness / readiness probes"]],["Capstone Demo",60,["Live order status over WebSockets","Notifications service sends emails","Record the full flow end-to-end"]]]}]};
  const NS = 'http://www.w3.org/2000/svg';
  const svg = document.documentElement;
  const KEY = 'node-ms-sprint-v1';
  let done = {};
  try { done = JSON.parse(localStorage.getItem(KEY) || '{}') || {}; } catch (e) {}
  const save = () => { try { localStorage.setItem(KEY, JSON.stringify(done)); } catch (e) {} };

  const el = (tag, attrs, parent, text) => {
    const n = document.createElementNS(NS, tag);
    for (const k in attrs) n.setAttribute(k, attrs[k]);
    if (text != null) n.textContent = text;
    if (parent) parent.appendChild(n);
    return n;
  };

  function render() {
    let all = 0, left = D.totalMin;
    D.phases.forEach((ph, p) => {
      let n = 0;
      ph.topics.forEach((_, i) => {
        const id = p + '-' + i;
        const card = document.getElementById('t-' + id);
        const on = !!done[id];
        card.classList.toggle('done', on);
        card.querySelector('.ring').style.fill = on ? ph.color : '';
        if (on) { n++; left -= ph.topics[i][1]; }
      });
      all += n;
      document.getElementById('c-' + p).textContent = n + '/' + ph.topics.length;
      document.getElementById('s-' + p).classList.toggle('done', n === ph.topics.length);
    });
    document.getElementById('bar').setAttribute('width', (600 * all / D.total).toFixed(1));
    document.getElementById('pct').textContent = all + ' / ' + D.total + ' built · ' + Math.round(left / 60) + 'h left';
  }

  function toggle(id) {
    if (done[id]) delete done[id]; else done[id] = 1;
    save(); render();
  }

  const overlay = document.getElementById('overlay');
  function close() { overlay.replaceChildren(); }

  function open(p, i) {
    close();
    const ph = D.phases[p];
    const [title, min, tasks] = ph.topics[i];
    const id = p + '-' + i;
    const card = document.getElementById('t-' + id).querySelector('.bg');
    const W = 600, H = 190 + tasks.length * 40;
    const x = 720 - W / 2;
    const vb = svg.viewBox.baseVal.height;
    const y = Math.max(20, Math.min(+card.getAttribute('y') - 40, vb - H - 20));

    el('rect', { id: 'scrim', width: '100%', height: '100%' }, overlay).addEventListener('click', close);
    const g = el('g', {}, overlay);
    el('rect', { class: 'pbg', x, y, width: W, height: H, rx: 18 }, g);
    el('rect', { x: x + 24, y, width: W - 48, height: 4, rx: 2, fill: ph.color }, g);
    el('text', { class: 'pkick', x: x + 32, y: y + 44, fill: ph.color }, g,
      'DAY ' + (p + 1) + ' · ' + ph.title.toUpperCase() + ' · ' + min + ' MIN');
    el('text', { class: 'ptitle', x: x + 32, y: y + 82 }, g, title);
    const cl = el('text', { class: 'pclose', x: x + W - 30, y: y + 46, 'text-anchor': 'middle' }, g, '×');
    cl.addEventListener('click', close);
    el('line', { x1: x + 32, x2: x + W - 32, y1: y + 104, y2: y + 104, stroke: 'var(--border)' }, g);

    tasks.forEach((t, k) => {
      const ty = y + 136 + k * 40;
      el('rect', { x: x + 32, y: ty - 15, width: 28, height: 22, rx: 6, fill: ph.color, opacity: .16 }, g);
      el('text', { class: 'pmono', x: x + 46, y: ty + 1, 'text-anchor': 'middle', fill: ph.color }, g, String(k + 1).padStart(2, '0'));
      el('text', { class: 'ptask', x: x + 74, y: ty + 1 }, g, t);
    });

    const on = !!done[id];
    const by = y + H - 58;
    const btn = el('g', { class: 'pbtn' }, g);
    el('rect', { x: x + 32, y: by, width: 180, height: 38, rx: 19,
      fill: on ? 'transparent' : ph.color, stroke: ph.color, 'stroke-width': 1.5 }, btn);
    el('text', { x: x + 122, y: by + 24, 'text-anchor': 'middle', fill: on ? ph.color : '#0b0f17' }, btn,
      on ? '✓ Built — undo' : 'Mark as built');
    btn.addEventListener('click', () => { toggle(id); open(p, i); });

    const nav = (dp, di, label, bx) => {
      const b = el('g', { class: 'pbtn' }, g);
      el('rect', { x: bx, y: by, width: 92, height: 38, rx: 19, fill: 'transparent', stroke: 'var(--border)' }, b);
      el('text', { x: bx + 46, y: by + 24, 'text-anchor': 'middle', fill: 'var(--text)' }, b, label);
      b.addEventListener('click', () => open(dp, di));
    };
    const flat = D.phases.flatMap((q, qp) => q.topics.map((_, qi) => [qp, qi]));
    const idx = flat.findIndex(([a, b]) => a === p && b === i);
    if (idx > 0) nav(...flat[idx - 1], '‹ Prev', x + W - 232);
    if (idx < flat.length - 1) nav(...flat[idx + 1], 'Next ›', x + W - 124);

    const r = svg.getBoundingClientRect();
    const s = r.height / vb;
    const top = y * s + r.top + window.scrollY;
    const bottom = (y + H) * s + r.top + window.scrollY;
    if (top < window.scrollY || bottom > window.scrollY + window.innerHeight) {
      window.scrollTo({ top: top - 24, behavior: 'smooth' });
    }
  }

  document.querySelectorAll('.card').forEach((c) => {
    const p = +c.dataset.p, i = +c.dataset.i;
    c.addEventListener('click', (e) => {
      if (e.target.closest('.check')) { toggle(p + '-' + i); return; }
      open(p, i);
    });
    c.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); open(p, i); }
    });
  });

  document.querySelectorAll('.chip').forEach((c) => c.addEventListener('click', () => {
    const r = svg.getBoundingClientRect();
    const s = r.height / svg.viewBox.baseVal.height;
    window.scrollTo({ top: D.phases[+c.dataset.jump].y * s + r.top + window.scrollY - 24, behavior: 'smooth' });
  }));

  document.getElementById('reset').addEventListener('click', () => {
    if (confirm('Reset all progress?')) { done = {}; save(); render(); }
  });
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') close(); });

  render();
})();
